class Solution {
public:
    string minWindow(string s, string t) {
        if (t.empty() || s.empty()) return "";
        // frequency of characters needed from t
        int need[128] = {0};
        for (char c : t) ++need[(int)c];
        int required = 0;
        for (int i = 0; i < 128; ++i) if (need[i] > 0) ++required;

        int have[128] = {0};
        int formed = 0;
        int left = 0, right = 0;
        int bestLen = INT_MAX, bestStart = 0;

        while (right < (int)s.size()) {
            char c = s[right];
            ++have[(int)c];
            if (need[(int)c] > 0 && have[(int)c] == need[(int)c])
                ++formed;

            // try to shrink the window
            while (left <= right && formed == required) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                char cl = s[left];
                if (need[(int)cl] > 0 && have[(int)cl] == need[(int)cl])
                    --formed;
                --have[(int)cl];
                ++left;
            }
            ++right;
        }

        if (bestLen == INT_MAX) return "";
        return s.substr(bestStart, bestLen);
    }
};
